cypress_script:
describe('Product List Search', () => {
  it('should display relevant products when a valid search term is entered', () => {
    cy.visit('https://automationexercise.com/products');
    cy.get('#search_product').type('Tshirt');
    cy.get('#submit_search').click();
    cy.url().should('include', 'search=');
    cy.get('.google-anno').should('be.visible');
  });
  it('should not change the product list when an invalid search term is entered', () => {
    cy.visit('https://automationexercise.com/products');
    cy.get('#search_product').type('NonExistingProduct');
    cy.get('#submit_search').click();
    cy.url().should('include', 'search=');
    cy.get('.google-anno').should('not.exist');
  });
});

playwright_script:
import { test } from '@playwright/test';

test.describe('Product List Search', () => {
  test('should display relevant products when a valid search term is entered', async ({ page }) => {
    await page.goto('https://automationexercise.com/products');
    await page.fill('#search_product', 'Tshirt');
    await page.click('#submit_search');
    await page.waitForURL(/.*search=/);
    await page.locator('.google-anno').isVisible();
  });
  test('should not change the product list when an invalid search term is entered', async ({ page }) => {
    await page.goto('https://automationexercise.com/products');
    await page.fill('#search_product', 'NonExistingProduct');
    await page.click('#submit_search');
    await page.waitForURL(/.*search=/);
    const products = await page.locator('.google-anno').count();
    expect(products).toBe(0);
  });
});
